from __future__ import annotations

import json
import subprocess
from pathlib import Path

import pytest

from src.idempotency import (
    ALREADY_APPLIED,
    APPLIED,
    FAILED,
    REPEATED,
    IdempotencyStore,
    apply_batch,
    comment_key,
    create_key,
    effect_key,
    normalize,
)
from src.client import WorkbenchError
from src.reconcile import reconcile, reconcile_decisions

# The reference vectors. Those holding U+001C-U+001F, U+0085 or U+FEFF, on which Python's
# whitespace and JavaScript's differ, were generated by running the n8n Idempotency check
# node's own code, and tests/test_n8n_parity.py checks every vector against it again.
VECTORS = json.loads(
    (Path(__file__).resolve().parent / "idempotency_vectors.json").read_text(encoding="utf-8")
)


@pytest.mark.parametrize("case", VECTORS["normalize"])
def test_normalize_vectors(case):
    assert normalize(case["in"]) == case["out"]


def test_normalize_handles_none():
    assert normalize(None) == ""


@pytest.mark.parametrize("case", VECTORS["effect_key"])
def test_effect_key_matches_pinned_vectors(case):
    assert effect_key(case["kind"], case["target"], case["content"]) == case["key"]


def test_new_and_update_keys_differ_for_same_text():
    assert effect_key("NEW", "", "ship it") != effect_key("UPDATE", "t1", "ship it")


def test_update_key_depends_on_target():
    assert effect_key("UPDATE", "t1", "x") != effect_key("UPDATE", "t2", "x")


def test_a_null_name_or_description_keys_like_an_absent_one():
    # A model that answers null means there is nothing there. The n8n Idempotency check
    # reads (j.name || '') and (j.description || ''), so the key does too: str(None) would
    # hash the word "None" and give one effect two keys in the store the app and n8n
    # share. The node itself is run in tests/test_n8n_parity.py; this holds without node.
    body, name = "alert on CDN errors", "[Dev] Null description"
    assert create_key({"name": None, "description": body}) == create_key({"description": body})
    assert create_key({"name": name, "description": None}) == create_key({"name": name})


# --- one name and one body per point ---

# A point in each shape it comes in: a task, an action item as extraction writes it, a
# point that carries its body as `detail` (an eval entry), and a task whose name is null.
POINTS = {
    "task": {"name": "[Dev] New alerting", "description": "alert on CDN errors"},
    "action item": {"what": "Alert on CDN errors", "context": "the CDN failed twice this week"},
    "eval entry": {"name": "Alert on CDN errors", "detail": "the CDN failed twice this week"},
    "null name": {"name": None, "description": "alert on CDN errors"},
}


@pytest.mark.parametrize("shape", list(POINTS))
def test_a_point_keys_alike_before_and_after_reconcile(shape):
    # reconcile() hands a point on as `name` and `detail`, and the plan applies that
    # record; the key must not care which of the two it is given. That holds only if
    # reconcile() and the key read a point's name and body by one definition.
    point = POINTS[shape]
    record = reconcile([dict(point)], [])[0]  # an empty board asks no model
    assert create_key(record) == create_key(point)
    target = {"target_id": "86abc"}
    assert comment_key({**record, **target}) == comment_key({**point, **target})


def test_a_meeting_decision_is_keyed_on_its_sentence_whatever_else_it_carries(monkeypatch):
    # A meeting decision is one sentence, and that sentence is its body: a rule, not a
    # fallback. Keyed through a fallback, a field given to meeting decisions later -- a
    # context, a description -- would become the body, re-key every comment already
    # applied for one, and the next run would post it again.
    monkeypatch.setattr("src.reconcile.ask", lambda system, prompt, max_tokens=400: (
        "DECISION: UPDATE\nTASK_ID: 86abc\nCONFIDENCE: 0.9\nREASON: same release"))
    board = [{"id": "86abc", "name": "[Release] Cut the August release"}]
    meeting_decision = {"what": "Ship Wednesday, cut payments", "affects": "the release",
                        "kind": "scope_change"}
    decided = reconcile_decisions([meeting_decision], board)[0]
    applied = effect_key("UPDATE", "86abc", "Ship Wednesday, cut payments")
    assert comment_key(decided) == applied
    for field in ("detail", "description", "context"):
        assert comment_key({**decided, field: "a field meeting decisions lack today"}) == applied


def test_reconcile_says_what_every_decision_affects(monkeypatch):
    # The rule above recognises a meeting decision by the `affects` it carries, and
    # reconcile_decisions stamps that field on every decision it hands on -- including one
    # the extraction wrote without it. Were the stamp to go, a decision would read as an
    # ordinary point, take its body from the fallback, and re-key in silence every comment
    # already applied for it. So the rule's precondition is pinned here, beside the rule.
    monkeypatch.setattr("src.reconcile.ask", lambda system, prompt, max_tokens=400: (
        "DECISION: UPDATE\nTASK_ID: 86abc\nCONFIDENCE: 0.9\nREASON: same release"))
    board = [{"id": "86abc", "name": "[Release] Cut the August release"}]
    extracted = {"what": "Ship Wednesday", "detail": "as the call left it"}
    decided = reconcile_decisions([extracted], board)[0]
    assert "affects" in decided
    assert comment_key(decided) == effect_key("UPDATE", "86abc", "Ship Wednesday")


# --- the file the store and the n8n nodes share ---

# Where this checkout is, asked of git rather than derived the way the module derives
# it: a test that repeats the code's own arithmetic passes when both are wrong together.
CHECKOUT = Path(subprocess.run(["git", "rev-parse", "--show-toplevel"],
                               cwd=Path(__file__).parent, capture_output=True,
                               text=True, check=True).stdout.strip())


def test_the_store_finds_its_file_under_wb_home(tmp_path, monkeypatch):
    # n8n runs outside the checkout and is pointed at it by WB_HOME. The store answers
    # "which file" the same way its nodes do, so the two share one file by construction
    # rather than by both being handed the same path.
    monkeypatch.setenv("WB_HOME", str(tmp_path))
    assert IdempotencyStore().path == tmp_path / "state" / "processed_effects.jsonl"


def test_a_trailing_slash_on_wb_home_still_names_one_file(tmp_path, monkeypatch):
    # The nodes build the path by joining strings, so a WB_HOME ending in a slash gives
    # them "/x//state/...". That is one file to the filesystem, and the store must not
    # answer with a different one.
    monkeypatch.setenv("WB_HOME", str(tmp_path) + "/")
    assert IdempotencyStore().path == tmp_path / "state" / "processed_effects.jsonl"


def test_a_relative_wb_home_is_refused_rather_than_kept(monkeypatch):
    # A relative WB_HOME resolves against whatever directory each process was started in,
    # and n8n's is not the app's — so both sides would go on working while quietly
    # keeping two stores, the one failure this rule exists to remove. The nodes refuse a
    # WB_HOME they cannot use; this side refuses one it cannot share.
    monkeypatch.setenv("WB_HOME", "relative/checkout")
    with pytest.raises(WorkbenchError) as exc:
        IdempotencyStore()
    assert "WB_HOME" in str(exc.value) and "absolute" in str(exc.value).lower()


def test_without_wb_home_the_store_file_is_the_checkout_s(monkeypatch):
    # Derived from one module's own location instead, two checkouts — or a packaged
    # install — quietly kept two stores, and every effect already applied came back new.
    monkeypatch.delenv("WB_HOME", raising=False)
    assert IdempotencyStore().path == CHECKOUT / "state" / "processed_effects.jsonl"


# --- the store runs an effect at most once ---

# What the caller says about the effect it is running. The store adds the key and the
# timestamp and writes the record itself, so the format has one definition.
RECORD = {"kind": "NEW", "target": None, "preview": "alert on CDN errors", "source": "app"}


def _effect(ran: list, info: str = "done", ok: bool = True):
    """An effect the store can run: it notes that it ran, and reports (ok, info) the way
    a write to the tracker reports itself."""

    def run():
        ran.append(info)
        return ok, info

    return run


def test_a_fresh_effect_runs_and_is_recorded(tmp_path):
    path = tmp_path / "s.jsonl"
    ran = []
    attempt = IdempotencyStore(path).apply_once("k1", _effect(ran), **RECORD)
    assert (attempt.outcome, attempt.info) == (APPLIED, "done")
    assert ran == ["done"]
    written = json.loads(path.read_text(encoding="utf-8"))
    # The record the n8n Mark processed node writes, field for field and in its order:
    # one store, one format, whichever side appended the line.
    assert list(written) == ["key", "kind", "target", "preview", "ts", "source"]
    assert {k: v for k, v in written.items() if k != "ts"} == dict(RECORD, key="k1")
    assert written["ts"].endswith("Z")


def test_a_record_keeps_the_first_60_characters_of_the_preview(tmp_path):
    # The preview is a glance at what was applied, cut where the node cuts it.
    path = tmp_path / "s.jsonl"
    IdempotencyStore(path).apply_once("k1", _effect([]), **dict(RECORD, preview="x" * 80))
    assert json.loads(path.read_text(encoding="utf-8"))["preview"] == "x" * 60


def test_a_key_the_file_already_held_is_already_applied_and_nothing_runs(tmp_path):
    # Two clicks are two store instances, and often two processes: what the first applied
    # the second must read off the file, or the second click writes everything again.
    path = tmp_path / "s.jsonl"
    IdempotencyStore(path).apply_once("k1", _effect([]), **RECORD)
    ran = []
    attempt = IdempotencyStore(path).apply_once("k1", _effect(ran), **RECORD)
    assert attempt.outcome == ALREADY_APPLIED
    assert ran == [] and len(path.read_text(encoding="utf-8").splitlines()) == 1


def test_a_second_identical_effect_in_one_run_is_a_repeat(tmp_path):
    # It was applied a moment ago, by this run. Calling that "already applied" tells the
    # person that the store stopped work it had seen before, which nothing had.
    path = tmp_path / "s.jsonl"
    store = IdempotencyStore(path)
    store.apply_once("k1", _effect([]), **RECORD)
    ran = []
    assert store.apply_once("k1", _effect(ran), **RECORD).outcome == REPEATED
    assert ran == [] and len(path.read_text(encoding="utf-8").splitlines()) == 1


def test_a_failed_effect_keeps_no_key_and_does_not_block_an_identical_one_after_it(tmp_path):
    # The reservation is released, so the same effect later in the same run is free to
    # run — and nothing is left on disk for the next run to skip.
    path = tmp_path / "s.jsonl"
    store = IdempotencyStore(path)
    ran = []
    attempt = store.apply_once("k1", _effect(ran, "no permission", ok=False), **RECORD)
    assert (attempt.outcome, attempt.info) == (FAILED, "no permission")
    assert not path.exists()
    assert store.apply_once("k1", _effect(ran, "retried"), **RECORD).outcome == APPLIED
    assert ran == ["no permission", "retried"]


def test_an_effect_that_raises_releases_its_key_and_the_error_reaches_the_caller(tmp_path):
    # A traceback out of the tracker is no reason to record the effect as applied, nor to
    # hold its key for the rest of the run — and it is not the store's to swallow.
    store = IdempotencyStore(tmp_path / "s.jsonl")

    def boom():
        raise RuntimeError("the tracker fell over")

    with pytest.raises(RuntimeError):
        store.apply_once("k1", boom, **RECORD)
    ran = []
    assert store.apply_once("k1", _effect(ran), **RECORD).outcome == APPLIED
    assert ran == ["done"]


def test_a_malformed_line_is_tolerated(tmp_path):
    p = tmp_path / "s.jsonl"
    p.write_text('{"key": "good"}\nnot json\n{"nokey": 1}\n', encoding="utf-8")
    ran = []
    assert IdempotencyStore(p).apply_once("good", _effect(ran), **RECORD).outcome == ALREADY_APPLIED
    assert ran == []


# --- the published demo: the same meeting twice ---


def test_a_second_run_of_the_same_meeting_applies_nothing(tmp_path):
    # The second run is a second store, reading the first one's records off the file:
    # that, not a set kept in memory, is what makes re-processing a meeting a no-op.
    effects = [("UPDATE", "t1", "saved cards unblocked"),
               ("NEW", "", "investigate ios funnel"),
               ("UPDATE", "t2", "crash fix in review")]
    path = tmp_path / "s.jsonl"
    first = apply_batch(effects, IdempotencyStore(path))
    second = apply_batch(effects, IdempotencyStore(path))
    assert first[APPLIED] == 3 and first[ALREADY_APPLIED] == 0
    assert second[APPLIED] == 0 and second[ALREADY_APPLIED] == 3


def test_the_same_effect_twice_in_one_run_is_applied_once_and_counted_as_a_repeat(tmp_path):
    effects = [("UPDATE", "t1", "same"), ("UPDATE", "t1", "same")]
    counts = apply_batch(effects, IdempotencyStore(tmp_path / "s.jsonl"))
    assert counts[APPLIED] == 1
    assert counts[REPEATED] == 1 and counts[ALREADY_APPLIED] == 0
